={{ { query: `query ContextoRespuesta($correo: String!, $threadId: String, $messageId: String!) {
  correo_existente: correos_proveedor(
    where: { gmail_message_id: { _eq: $messageId } }
    limit: 1
  ) { id estado_correo origen_estado analisis_agente }
  solicitud_proveedores(where: {
    proveedor_asociado: { correo: { _ilike: $correo } }
    solicitud_cotizacion: { estado: { _eq: "inicio" } }
  }) {
    solicitud_id proveedor_id numero_coordinaciones considerado ultimo_correo_at
    aclaraciones_pendientes(where: { estado: { _eq: "abierta" } }) { id descripcion }
    proveedor_asociado { nombre correo }
    solicitud_cotizacion { codigo nombre estado fecha_limite creado_por proyecto_asociado { codigo nombre } }
  }
  envios_solicitud(where: {
    _or: [
      { gmail_thread_id: { _eq: $threadId } }
      { destinatario: { _ilike: $correo } }
    ]
  }) {
    solicitud_id proveedor_id gmail_thread_id destinatario
    proveedor_asociado { nombre correo }
    solicitud_cotizacion { codigo nombre estado fecha_limite creado_por proyecto_asociado { codigo nombre } }
    participacion_seguimiento {
      numero_coordinaciones considerado ultimo_correo_at
      aclaraciones_pendientes(where: { estado: { _eq: "abierta" } }) { id descripcion }
    }
  }
  correos_proveedor(
    where: { _or: [
      { gmail_thread_id: { _eq: $threadId } }
      { remitente: { _ilike: $correo } }
    ] }
    order_by: { recibido_at: desc }
    limit: 20
  ) { solicitud_id proveedor_id gmail_message_id gmail_thread_id asunto cuerpo_texto recibido_at estado_correo origen_estado analisis_agente }
}`, variables: { correo: $json.remitente, threadId: $json.threadId || '__sin_hilo__', messageId: $json.messageId } } }}

