const VERSION_ANALISIS = 3;
const correo = $('Normalizar correo').item.json;
const datos = $json.data;
const existente = datos?.correo_existente?.[0];
const versionExistente = Number(existente?.analisis_agente?._costflow_version ?? 0);
if (existente && versionExistente >= VERSION_ANALISIS) {
  return { json: { omitir: true, motivo: 'correo_ya_procesado', messageId: correo.messageId } };
}
const hash128 = (valor) => {
  const texto = String(valor);
  let h1 = 1779033703, h2 = 3144134277, h3 = 1013904242, h4 = 2773480762;
  for (let i = 0; i < texto.length; i += 1) {
    const k = texto.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067);
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233);
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213);
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179);
  return [h1 ^ h2 ^ h3 ^ h4, h2 ^ h1, h3 ^ h1, h4 ^ h1]
    .map((item) => (item >>> 0).toString(16).padStart(8, '0')).join('');
};
const uuidCorreo = (messageId) => {
  const hex = hash128(messageId);
  const variante = ((parseInt(hex[16], 16) & 3) | 8).toString(16);
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-${variante}${hex.slice(17, 20)}-${hex.slice(20)}`;
};
const correoId = existente?.id ?? uuidCorreo(correo.messageId);
const porClave = new Map();
for (const participacion of datos?.solicitud_proveedores ?? []) {
  porClave.set(`${participacion.solicitud_id}:${participacion.proveedor_id}`, participacion);
}
for (const envio of datos?.envios_solicitud ?? []) {
  const clave = `${envio.solicitud_id}:${envio.proveedor_id}`;
  const coincideHilo = Boolean(correo.threadId && envio.gmail_thread_id === correo.threadId);
  if (!porClave.has(clave) || coincideHilo) {
    porClave.set(clave, {
      solicitud_id: envio.solicitud_id,
      proveedor_id: envio.proveedor_id,
      numero_coordinaciones: envio.participacion_seguimiento?.numero_coordinaciones ?? 0,
      considerado: envio.participacion_seguimiento?.considerado ?? true,
      ultimo_correo_at: envio.participacion_seguimiento?.ultimo_correo_at ?? null,
      aclaraciones_pendientes: envio.participacion_seguimiento?.aclaraciones_pendientes ?? [],
      proveedor_asociado: envio.proveedor_asociado,
      solicitud_cotizacion: envio.solicitud_cotizacion,
      coincidencia_hilo: coincideHilo,
    });
  }
}
const candidatos = [...porClave.values()].sort((a, b) => Number(b.coincidencia_hilo) - Number(a.coincidencia_hilo));
if (!candidatos.length) {
  return { json: { omitir: true, motivo: 'sin_candidato', messageId: correo.messageId } };
}
const prompt = `Analiza una respuesta de proveedor de CostFlow. Devuelve solamente JSON válido.
Debes asociar el correo con exactamente uno de los candidatos y proponer uno de estos dos estados preliminares:
- respuesta_sin_nueva_cotizacion_ni_ficha_tecnica: confirmó recepción sin adjuntar nueva cotización o ficha técnica, realizó una consulta, rechazó participar o envió otra comunicación sin esos documentos.
- cotizacion_o_ficha_tecnica_recibida: existe evidencia de una cotización, propuesta económica, ficha técnica, catálogo, manual o documentación técnica recibida en el correo o sus adjuntos.
Nunca propongas cotizacion_o_ficha_tecnica_aceptada_final. Ese estado pertenece exclusivamente al especialista.
Prioriza coincidencia_hilo; como respaldo usa correo, razón social, asunto, código, proyecto e historial.
Devuelve: solicitudId, proveedorId, estadoCorreo, aclaraciones (array de textos explícitos), evidencia (array de textos), confianza (0 a 1), razon.

CORREO NUEVO:
${JSON.stringify(correo)}

CANDIDATOS:
${JSON.stringify(candidatos)}

HISTORIAL:
${JSON.stringify(datos?.correos_proveedor ?? [])}`;
return { json: { ...correo, correoId, candidatos, prompt, versionAnalisis: VERSION_ANALISIS } };

const contexto = $('Preparar contexto').item.json;
let salida = $json.output ?? $json.text ?? $json;
if (typeof salida === 'string') {
  salida = salida.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  salida = JSON.parse(salida);
}
const estados = new Set([
  'respuesta_sin_nueva_cotizacion_ni_ficha_tecnica',
  'cotizacion_o_ficha_tecnica_recibida',
]);
const candidato = contexto.candidatos.find((item) => item.solicitud_id === salida.solicitudId && item.proveedor_id === salida.proveedorId);
if (!candidato) throw new Error('El agente no pudo asociar el correo con una solicitud y proveedor válidos.');
if (!estados.has(salida.estadoCorreo)) throw new Error('El agente devolvió un estado preliminar no permitido.');
const confianzaRecibida = Number(salida.confianza);
const confianza = Number.isFinite(confianzaRecibida) && confianzaRecibida >= 0 && confianzaRecibida <= 1
  ? confianzaRecibida : 0;
const fechaRecibida = new Date(contexto.recibidoAt);
if (Number.isNaN(fechaRecibida.getTime())) throw new Error('Gmail entregó una fecha de recepción inválida.');
const fechaCorreo = fechaRecibida.toLocaleDateString('en-CA', { timeZone: 'America/Lima' });
const fueraPlazo = fechaCorreo > candidato.solicitud_cotizacion.fecha_limite;
const requiereRevision = confianza < 0.8;
const aclaraciones = Array.isArray(salida.aclaraciones)
  ? salida.aclaraciones.filter((item) => typeof item === 'string' && item.trim()).map((item) => item.trim())
  : [];
const evidencia = Array.isArray(salida.evidencia)
  ? salida.evidencia.filter((item) => typeof item === 'string' && item.trim()).map((item) => item.trim())
  : [];
const solicitudActiva = candidato.solicitud_cotizacion.estado === 'inicio';
const proveedorActivo = candidato.considerado !== false;
const notificar = solicitudActiva && proveedorActivo && !fueraPlazo;
const registrarAclaraciones = notificar && !requiereRevision && aclaraciones.length > 0;
const etiquetas = {
  respuesta_sin_nueva_cotizacion_ni_ficha_tecnica: 'respuesta sin nueva cotización ni ficha técnica',
  cotizacion_o_ficha_tecnica_recibida: 'cotización o ficha técnica recibida',
};
const titulo = requiereRevision
  ? `Revisión necesaria: ${candidato.solicitud_cotizacion.codigo} — ${candidato.proveedor_asociado.nombre}`
  : `${candidato.solicitud_cotizacion.codigo} — ${candidato.proveedor_asociado.nombre}: ${etiquetas[salida.estadoCorreo]}`;
const mensaje = requiereRevision
  ? `La detección preliminar tuvo una confianza de ${Math.round(confianza * 100)} %. Revisa el correo y asigna su estado.`
  : String(salida.razon || evidencia.join(' · ') || 'Se recibió una respuesta del proveedor.');
const analisis = { ...salida, _costflow_version: contexto.versionAnalisis };
return { json: {
  notificar, registrarAclaraciones,
  correo: {
    id: contexto.correoId,
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    gmail_message_id: contexto.messageId,
    gmail_thread_id: contexto.threadId,
    remitente: contexto.remitente,
    destinatarios: contexto.destinatarios,
    asunto: contexto.asunto,
    cuerpo_texto: contexto.cuerpo,
    adjuntos: contexto.adjuntos,
    recibido_at: contexto.recibidoAt,
    fuera_plazo: fueraPlazo,
    estado_correo: salida.estadoCorreo,
    origen_estado: 'agente',
    analisis_agente: analisis,
  },
  aclaraciones: aclaraciones.map((descripcion, indice) => ({
    correo_id: contexto.correoId,
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    dedupe_key: `${contexto.messageId}:${indice}`,
    descripcion,
  })),
  notificacion: {
    usuario_id: candidato.solicitud_cotizacion.creado_por,
    solicitud_id: candidato.solicitud_id,
    proveedor_id: candidato.proveedor_id,
    tipo: requiereRevision ? 'requiere_revision' : 'cambio_respuesta',
    titulo,
    mensaje,
    datos: {
      gmail_message_id: contexto.messageId,
      estado_preliminar: salida.estadoCorreo,
      confianza, evidencia, adjuntos: contexto.adjuntos,
    },
    dedupe_key: `correo:${contexto.messageId}`,
  },
} };

