={{ { query: `mutation RegistrarRespuesta($correo: correos_proveedor_insert_input!, $aclaraciones: [aclaraciones_proveedor_insert_input!]!, $notificacion: notificaciones_insert_input!, $registrarAclaraciones: Boolean!, $notificar: Boolean!) {
  insert_correos_proveedor_one(
    object: $correo
    on_conflict: { constraint: correos_proveedor_gmail_message_id_key, update_columns: [analisis_agente] }
  ) { id estado_correo origen_estado }
  insert_aclaraciones_proveedor(
    objects: $aclaraciones
    on_conflict: { constraint: aclaraciones_proveedor_dedupe_key_key, update_columns: [] }
  ) @include(if: $registrarAclaraciones) { affected_rows }
  insert_notificaciones_one(
    object: $notificacion
    on_conflict: { constraint: notificaciones_dedupe_key_key, update_columns: [titulo, mensaje, datos] }
  ) @include(if: $notificar) { id }
}`, variables: { correo: $json.correo, aclaraciones: $json.aclaraciones, notificacion: $json.notificacion, registrarAclaraciones: $json.registrarAclaraciones, notificar: $json.notificar } } }}
